begin
  for template in select * from jsonb_array_elements(payload)
  loop
    insert into surveyor.survey_templates(code, name, description, status, denominator, passing_score, source_document)
    values (
      template ->> 'code',
      template ->> 'name',
      template ->> 'description',
      'active',
      (template ->> 'denominator')::numeric,
      (template ->> 'passing_score')::numeric,
      'Permenkes 17 Tahun 2024 OCR seed'
    )
    on conflict (code) do update set
      name = excluded.name,
      description = excluded.description,
      status = excluded.status,
      denominator = excluded.denominator,
      passing_score = excluded.passing_score,
      source_document = excluded.source_document,
      updated_at = now()
    returning id into current_template_id;

    insert into surveyor.formula_rules(template_id, name, expression, denominator, passing_score)
    values (current_template_id, 'Skor Total Inspeksi', '100 - ((total_nonconformity / denominator) * 100)', (template ->> 'denominator')::numeric, (template ->> 'passing_score')::numeric)
    on conflict (template_id, name) do update set denominator = excluded.denominator, passing_score = excluded.passing_score, updated_at = now();

    delete from surveyor.survey_questions where surveyor.survey_questions.template_id = current_template_id;
    delete from surveyor.survey_sections where surveyor.survey_sections.template_id = current_template_id;

    section_index := 0;
    for section_payload in select distinct jsonb_build_object('title', q ->> 'section') from jsonb_array_elements(template -> 'questions') q
    loop
      section_index := section_index + 1;
      insert into surveyor.survey_sections(template_id, title, sort_order)
      values (current_template_id, coalesce(nullif(section_payload ->> 'title', ''), 'Umum'), section_index)
      returning id into current_section_id;
    end loop;

    for question_payload in select * from jsonb_array_elements(template -> 'questions')
    loop
      select id into current_section_id
      from surveyor.survey_sections
      where surveyor.survey_sections.template_id = current_template_id
        and title = coalesce(nullif(question_payload ->> 'section', ''), 'Umum')
      limit 1;

      insert into surveyor.survey_questions(template_id, section_id, label, question_type, weight, is_required, is_active, sort_order)
      values (
        current_template_id,
        current_section_id,
        question_payload ->> 'label',
        'checkbox',
        (question_payload ->> 'weight')::numeric,
        false,
        true,
        (question_payload ->> 'sort_order')::integer
      );
    end loop;
  end loop;
end;
$$;
